ridge_empty_plot &lt;- function(title, message) {
  ggplot() +
    annotate("text", x = 0, y = 0, label = message) +
    theme_void() +
    labs(title = title)
}

manual_ridgeline &lt;- function(df, vars, title,
                             positive_only = FALSE, log10_x = FALSE,
                             cap_quantile = NULL, x_labels = comma,
                             x_axis_title = NULL) {
  plot_df &lt;- df |&gt;
    select(all_of(vars)) |&gt;
    pivot_longer(everything(), names_to = "variable", values_to = "value") |&gt;
    mutate(value = suppressWarnings(as.numeric(value))) |&gt;
    filter(is.finite(value))

  if (positive_only) {
    plot_df &lt;- plot_df |&gt; filter(value &gt; 0)
  }

  if (nrow(plot_df) == 0) {
    return(ridge_empty_plot(title, "No finite values available for this variable group."))
  }

  if (log10_x) {
    plot_df &lt;- plot_df |&gt;
      mutate(value_plot = log10(value + 1))
  } else if (!is.null(cap_quantile)) {
    cap_value &lt;- quantile(plot_df$value, cap_quantile, na.rm = TRUE)
    plot_df &lt;- plot_df |&gt;
      mutate(value_plot = pmin(value, cap_value))
  } else {
    plot_df &lt;- plot_df |&gt;
      mutate(value_plot = value)
  }

  variable_levels &lt;- rev(vars)

  density_df &lt;- plot_df |&gt;
    mutate(variable = factor(variable, levels = variable_levels)) |&gt;
    group_by(variable) |&gt;
    group_modify(~{
      if (nrow(.x) &lt; 2 || n_distinct(.x$value_plot) &lt; 2) {
        return(tibble(x = numeric(), density = numeric()))
      }
      density_obj &lt;- density(.x$value_plot, n = 256, na.rm = TRUE, from = 0)
      tibble(x = pmax(density_obj$x, 0), density = density_obj$y)
    }) |&gt;
    ungroup() |&gt;
    group_by(variable) |&gt;
    mutate(
      y_base = as.numeric(variable),
      y_ridge = y_base + density / max(density, na.rm = TRUE) * 0.82
    ) |&gt;
    ungroup()

  if (nrow(density_df) == 0) {
    return(ridge_empty_plot(title, "Not enough variation to estimate density ridges."))
  }

  p &lt;- ggplot(density_df, aes(x = x, group = variable, fill = variable)) +
    geom_ribbon(aes(ymin = y_base, ymax = y_ridge), alpha = 0.68, colour = NA) +
    geom_line(aes(y = y_ridge, colour = variable), linewidth = 0.45, show.legend = FALSE) +
    scale_y_continuous(
      breaks = seq_along(variable_levels),
      labels = variable_levels,
      expand = expansion(mult = c(0.03, 0.10))
    ) +
    guides(fill = "none") +
    labs(
      title = title,
      x = x_axis_title,
      y = NULL
    ) +
    theme(
      panel.grid.major.y = element_blank(),
      panel.grid.minor = element_blank()
    )

  if (log10_x) {
    p + scale_x_continuous(
      limits = c(0, NA),
      expand = expansion(mult = c(0, 0.03)),
      labels = function(x) x_labels(10^x - 1)
    )
  } else {
    p + scale_x_continuous(
      limits = c(0, NA),
      expand = expansion(mult = c(0, 0.03)),
      labels = x_labels
    )
  }
}

